"""The synthetic corpus is versioned: its generated bytes match the pinned manifest (Phase 4).

If a generator changes, this test fails. The fix is to bump CORPUS_VERSION, regenerate the manifest
and record the change in docs/PHASE4_SYNTHETIC_CORPUS.md, so no expected result moves silently.
"""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

from tests.support.parse_corpus import CORPUS_VERSION, corpus

MANIFEST = Path(__file__).resolve().parents[1] / "support" / "parse_corpus_manifest.json"


def test_the_generated_corpus_matches_the_pinned_manifest() -> None:
    pinned = json.loads(MANIFEST.read_text(encoding="utf-8"))
    assert pinned["corpus_version"] == CORPUS_VERSION

    generated = {
        case.case_id: {
            "category": case.category,
            "mime": case.mime,
            "expected_status": case.expected_status,
            "expected_class": case.expected_class,
            "size_bytes": len(case.data),
            "sha256": hashlib.sha256(case.data).hexdigest(),
        }
        for case in corpus()
    }
    assert generated == pinned["cases"]


def test_every_category_named_in_the_plan_has_at_least_one_case() -> None:
    categories = {case.category for case in corpus()}
    assert categories == {"valid", "invalid", "partial", "oversized", "restricted", "quarantined"}
